// ADR-066 Block 7: compute the finish-side session result from the waiter callback payload.
// Ports the doc-enumeration (Files API) + usd_cost (token tiers + runtime + web-search) + cost_impact
// + consolidated-warning classification from execute-agent-session 'Build Final Output' (the SYNC path
// computes these inside the sub-workflow; the async path returned at handoff, so we compute them here).
// KEEP THE COST MATH / DOC-MIME MAP IN SYNC WITH execute-agent-session 'Build Final Output'.
const body = $('Finish Webhook').first().json.body || {};
let key = '';
try { const k = $('Get Anthropic Key').first().json || {}; key = (k.key || k.get_anthropic_key || '').toString(); } catch (e) {}
let warnings = Array.isArray(body.warnings) ? body.warnings.slice() : [];
const usage = (body.session_usage && typeof body.session_usage === 'object') ? body.session_usage : {};
let output_blocks = Array.isArray(body.output_blocks) ? body.output_blocks : [];
const outcome = body.outcome;
let status = 'completed';
if (outcome === 'deadline') status = 'partial';
else if (outcome === 'terminated' || outcome === 'drive_error') status = 'failed';
else if (outcome === 'max_rounds') status = 'partial';
else if (outcome === 'poll_error') status = 'partial';
// clickup MCP auth failure is non-fatal; WARN only when the user IS onboarded (scope==='scoped').
if (body.clickup_auth_error_json && body.clickup_scope === 'scoped') { warnings.push({ source: 'managed-agents/clickup-scope-failed', err: 'Zakresowany dostep ClickUp (discovery) zawiodl mimo aktywnego poswiadczenia uzytkownika ' + (body.caller_user_id || '?') + ' - sprawdz token/MCP (mcp.clickup.com); szczegoly: ' + String(body.clickup_auth_error_json).slice(0,200), severity: 'WARN' }); }
if (outcome === 'delivered' && output_blocks.length === 0) { warnings.push({ source: 'output-adapter/deliver-output-empty', err: 'Agent wywolal deliver_output, ale tablica blokow byla pusta lub w nieobslugiwanym formacie (np. blocks jako string) - odpowiedz moglaby trafic jako pusty komentarz', severity: 'WARN' }); }

// --- enumerate session OUTPUT office-docs (xlsx/docx/pptx/pdf). Downloadable from the Files API
// (Block 0). Authoritative, agent-independent source of produced doc file_ids. Fail-soft: listing
// failure -> WARN + empty doc_files. ~2.5s settle for the post-idle index lag.
let doc_files = [];
const DOC_MIMES = {
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx',
  'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xlsx',
  'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'pptx',
  'application/pdf': 'pdf'
};
if ((status === 'completed' || status === 'partial') && body.session_id && key) {
  try {
    await new Promise(function(r){ setTimeout(r, 2500); });
    const dres = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.anthropic.com/v1/files?scope_id=' + encodeURIComponent(body.session_id), headers: { 'x-api-key': key, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'managed-agents-2026-04-01,files-api-2025-04-14' }, json: true, returnFullResponse: true, timeout: 30000 });
    const ddata = (dres.body && Array.isArray(dres.body.data)) ? dres.body.data : [];
    for (const f of ddata) {
      const mime = f.mime_type || '';
      const ext = DOC_MIMES[mime];
      if (f.downloadable === true && ext) doc_files.push({ file_id: f.id, filename: f.filename || (String(f.id) + '.' + ext), mime: mime, size_bytes: f.size_bytes || 0 });
    }
  } catch (e) {
    warnings.push({ source: 'managed-agents/doc-list-failed', err: 'Nie udalo sie wylistowac plikow wyjsciowych sesji (dokumenty moga nie zostac dostarczone): ' + String((e && e.message) || e).slice(0,200), severity: 'WARN' });
  }
}

// --- session USD cost = token tiers + runtime + web search. (Image cost is logged per-image.)
const PRICES = {
  'claude-haiku-4-5':  { in: 1.00,  out: 5.00 },
  'claude-sonnet-4-6': { in: 3.00,  out: 15.00 },
  'claude-opus-4-8':   { in: 5.00,  out: 25.00 },
  'claude-fable-5':    { in: 10.00, out: 50.00 }
};
const RUNTIME_USD_PER_HOUR = 0.08;
const WEB_SEARCH_USD_PER_CALL = 0.01;
const model = body.model_id || '';
const cc = usage.cache_creation || {};
const tIn = Number(usage.input_tokens || 0);
const tOut = Number(usage.output_tokens || 0);
const tWrite5m = Number(cc.ephemeral_5m_input_tokens || 0);
const tWrite1h = Number(cc.ephemeral_1h_input_tokens || 0);
const tRead = Number(usage.cache_read_input_tokens || 0);
const dur = Number(body.duration_seconds || 0);
const ws = Number(body.web_search_count || 0);
const p = PRICES[model];
if (!p) warnings.push({ source: 'managed-agents/cost-model-unknown', err: 'Brak cennika dla modelu ' + (model || '?') + ' - koszt sesji oszacowano cennikiem Opus 4.8 (gorny prog)', severity: 'WARN' });
const pr = p || PRICES['claude-opus-4-8'];
const tokenCost = (tIn/1e6)*pr.in + (tOut/1e6)*pr.out + (tWrite5m/1e6)*pr.in*1.25 + (tWrite1h/1e6)*pr.in*2.0 + (tRead/1e6)*pr.in*0.1;
const runtimeCost = RUNTIME_USD_PER_HOUR * (dur/3600);
const webSearchCost = ws * WEB_SEARCH_USD_PER_CALL;
const usd_cost = Number((tokenCost + runtimeCost + webSearchCost).toFixed(6));
if ((status === 'completed' || status === 'partial') && tIn === 0 && tOut === 0 && tRead === 0 && tWrite5m === 0 && tWrite1h === 0) warnings.push({ source: 'managed-agents/cost-usage-missing', err: 'Sesja bez danych uzycia tokenow - koszt sesji moze byc zanizony', severity: 'WARN' });
const ALLOWED = ['Niski','Średni','Wysoki','Krytycznie ważne','n/d - zadanie nie jest dla AI'];
const cost_impact = (ALLOWED.indexOf(body.impact) >= 0) ? body.impact : null;

// consolidated alert (async analog of Classify Alert). NOTE: does NOT fire the non-delivery CRITICAL
// (Publish Managed Result's Alert Non-Delivery does that) nor front-half warnings (not in body.warnings
// - Block 5 carry-forward). Only the session-level DEGRADATION warnings computed here + tool-bridge.
let do_alert = false, _sev = 'WARN', _msg = '', _details = '';
if (warnings.length > 0) { do_alert = true; const hasCrit = warnings.some(function(w){ return w.severity === 'CRITICAL'; }); _sev = hasCrit ? 'CRITICAL' : 'WARN'; _msg = 'Sesja Managed Agents (async waiter) zakonczona z ostrzezeniami (' + warnings.length + ') [status: ' + status + '] dla zadania ' + (body.clickup_task_id || '?'); _details = warnings.map(function(w){ return (w.source || '') + ': ' + (w.err || ''); }).join(' | ').slice(0,1500); }

return [{ json: {
  status: status,
  doc_files_json: JSON.stringify(doc_files),
  usd_cost: usd_cost,
  cost_impact: cost_impact,
  input_tokens: tIn,
  output_tokens: tOut,
  model_used: model,
  warnings: warnings,
  do_alert: do_alert,
  _sev: _sev,
  _msg: _msg,
  _details: _details
} }];
